}

 

.earthworm .tessera-eyebrow-container {

    margin: 3rem auto 1rem;

}

 

.earthworm p, .earthworm a {

    font-weight: bold;

}

 

/* AUDIO PLAYER */

 

.audio {

    margin-top: 2rem;

}

 

.audio iframe {

    width: 300px;

}

 

/* ———— MOBILE TWEAKS ———— */

 

/* Making the title text wrap on small screens */

 

@media (max-width: 460px) {

  #header h1 a {

    padding: 0;

    line-height: 1;

  }

