}



#page-content div.stickynote.tilt-light {

    transform: rotate(-0.5deg);

}



#page-content div.stickynote.tilt-medium {

    transform: rotate(-2deg);

}



#page-content div.stickynote.tilt-heavy {

    transform: rotate(-3deg);

}



