    }

}



#header h1 a span {

    margin-left: 0.65rem;

}



#header h1 a::before {

    width: calc(var(--base-header-height) * 0.65);

    min-width: calc(var(--base-header-height) * 0.70);

}



#header h1 a span {

    text-align: center;

    display: inline-block;

    width: max-content;

    min-width: max-content;

    height: unset;

}



#header h1 a span::before,

#header h1 a span::after {

    display: block;

