    clamp(calc(var(--main-content-width) / -100), calc((87.5vw - 95%) / -2), -2rem)

    margin-left: 1.25rem;

}



/* Tilt Controls */

#page-content div.stickynote.tilt-none {

    transform: rotate(0deg);

}



