/* This is CSS that will not be part of theme, just for the page itself */



/* SCP HEADER */

.scp-header {

    position: relative;

    width: 100%;

    height: 80px;

    margin: 0;

    padding: 10px 0;

}



.scp-header .scp-logo {

    position: absolute;

    left: -14px;

    top: 50%;

    transform: translateY(-50%);

    width: 80px;

    height: 80px;

    border-radius: 50%;

    overflow: hidden;

}



