[[module css]]

@import url('https://chinese-fonts-cdn.deno.dev/packages/syst/dist/SourceHanSerifCN/result.css');

@import url('https://fonts.googleapis.com/css2?family=Noto+Sans+SC&display=swap');

@import url('https://fonts.googleapis.com/css2?family=Afacad+Flux&display=swap');

@import url('https://fonts.googleapis.com/css2?family=Titillium+Web&display=swap');

:root {

  --title-font: 'Afacad Flux', 'Source Han Serif CN VF', serif;

  --body-font:  'Titillium Web', 'Noto Sans SC', sans-serif;

  --bg-img: url(http://starstrucked.wikidot.com/local--files/secure-shiv-nights/Reflection.png);

  --blur-mode: block;

  --bg-blur-filter: 0px;

  --prologue: "War is father of everything, war is king of everything.";

  --prologue-setting: visible;

  --prologue-author: "";

  --prologue-author-setting: hidden;

  --introduction: "War is father of everything, war is king of everything.";

  --introduction-setting: None;

  --primary-color: 16, 5, 5;

  --secondary-color: 236, 246, 253;

  --link-color: 176,0,0;

  --new-link-color: 225,0,0;

  --display-mode: 25vh;



/* DONT TOUCH BELOW */

  --background-gradient: linear-gradient(to bottom, rgb(var(--primary-color), 0.75) 20%, transparent);

 #page-title

{

display: none !important;

}

}



body {

    background: transparent;

    color: rgb(var(--secondary-color));

 

    font-family: var(--body-font);

    font-weight: 200;

    font-size: 0.925em;

}

 

body:not(#interwiki body)::before {

    content: " ";

    position: fixed;

    display: block;

    z-index: -2;

 

    top: 0;

    width: 100%;

    height: 100vh;

    background: var(--bg-img);

    background-size: cover;

    background-position: center;

}

 

a, a:visited, h1  {

    color: rgb(var(--link-color));

}

 

#side-bar a:visited {

  color: unset;

  color: rgb(var(--link-color));

}

 

a.newpage {

    color: rgb(var(--new-link-color));

}

 

hr {

  background: rgb(var(--secondary-color), .15);

  box-shadow: 0 0 10px rgb(0, 0, 0);

  backdrop-filter: brightness(3) contrast(1.1);

  -webkit-backdrop-filter: brightness(3) contrast(1.1);

}

 

strong {

  font-weight: bold;

}

 

h1, h2, h3, h4, h5, h6, #page-title {

    font-family: var(--title-font);

}

 

* {

  scrollbar-width: thin;

  scrollbar-color: rgb(var(--link-color))  rgb(var(--primary-color));

}

 

#avatar-hover-container {

  display:none !important;

}

 

div#container-wrap {

    background: none;

}

 

#header {

  display: grid;

  grid-template-columns: 3rem 1fr 3rem 3rem;

  grid-template-areas:'open-menu top-bar search user';

 

  justify-items: center;

  align-items: center;

  position: fixed;

  z-index: 10;

  max-width: 100%;

  width: 100%;

  margin: 0;

  padding: 0;

  background: transparent;

  backdrop-filter: blur(2px);

  -webkit-backdrop-filter: blur(2px);

  height: 3em;

  grid-template-rows: 3em;

}

 

#top-bar .open-menu a {

  grid-area:open-menu;

  display: flex;

  justify-content: center;

}

 

#top-bar {

  grid-area:top-bar;

  top: 1rem !important;

  left: 0;

  margin-left: 1rem;

 

  align-items: stretch;

  display: flex;

  flex-direction: row;

  justify-content: flex-start;

}

 

#search-top-box {

  grid-area:search;

  width: 100%;

  display: flex;

  justify-content: flex-end;

}

 

#login-status {

  grid-area:user;

  top: 2em;

  display: flex;

  justify-content: center;

}

 

#top-bar ul {

  float: unset;

}

 

#top-bar ul {

  flex: 1 0 100px;

}

 

#top-bar ul li ul {

  flex-direction: column;

}

 

#top-bar ul li.sfhover a, #top-bar ul li:hover a {

  background: transparent;

  color: rgb(var(--link-color));

  border-left: solid 1px transparent;

  border-right: solid 1px transparent;

}

 

#top-bar ul li ul {

  border: transparent;

  box-shadow: none;

  backdrop-filter: blur(4px);

  -webkit-backdrop-filter: blur(4px);

}

 

#top-bar ul li a {

  border-left: solid 1px transparent;

  border-right: solid 1px transparent;

  text-shadow: 0px 0px 5px black;

}

 

#top-bar ul li.sfhover ul li a, #top-bar ul li:hover ul li a {

  border-top: 1px solid rgba(var(--secondary-color), 0.33);

  text-shadow: 0px 0px 5px black;

}

 

@media (max-width: 767px) {

.mobile-top-bar {

  display: flex;

  justify-content: flex-start;

  max-width: 100%;

  width: 100%;

  flex-direction: row;

  }

}

 

@media (max-width: 479px) {

  .mobile-top-bar {

    font-size: 67%;

  }

}

 

#header h1 span, #header h2 span {

    display:none;

}

 

#extrac-div-1 {

    position: absolute;

    top: calc(var(--display-mode) / 2);

    left: 50%;

    transform: translateX(-50%);

    padding-left: 1em;

    padding-right: 1em;

    z-index: 2;

    pointer-events: var(--introduction-setting);

    width: 50%;

 

    display: flex;

    flex-direction: column;

}

 

#extrac-div-1::before {

    line-height: 1.5em;

    font-size: 1.5em;

    font-family: var(--title-font);

    font-weight: 400;

    text-shadow: 0px 0px 5px black;

 

    content: var(--prologue);

    color: rgb(var(--secondary-color));

    visibility: var(--prologue-setting);

    display: block;

 

    text-align: center;

    transition: font-size 0.3s ease, background-size 0.3s ease;

}

 

#extrac-div-1:hover::before {

    font-size: 1.25em;

    content: var(--introduction);

    background:

        linear-gradient(rgb(var(--secondary-color)), rgb(var(--secondary-color))) left top,

        linear-gradient(rgb(var(--secondary-color)), rgb(var(--secondary-color))) left top,

        linear-gradient(rgb(var(--secondary-color)), rgb(var(--secondary-color))) right bottom,

        linear-gradient(rgb(var(--secondary-color)), rgb(var(--secondary-color))) right bottom;

    background-position:

        left top, left top,

        right bottom, right bottom;

    background-repeat: no-repeat;

    background-size:

        1px 5px, 5px 1px,

        1px 5px, 5px 1px;

}

 

#extrac-div-1::after {

    line-height: 1.5em;

    font-size: 1.25em;

    font-family: var(--title-font);

    text-shadow: 0px 0px 3px rgba(var(--primary-color));

 

    content: var(--prologue-author);

    color: rgb(var(--secondary-color));

    visibility: var(--prologue-author-setting);

    display: block;

 

    text-align: right;

    transition: font-size 0.3s ease, background-size 0.3s ease;

}

 

@media (min-width: 1px) and (max-width: 1000px) {

  #extrac-div-1{

    width: 80%;

 }

 

 #page-title {

     font-size: 4em;

 }

 

 #top-bar {

   top: 1rem !important;

 }

 

 #top-bar li {

  margin-left: -0.6rem;

 }

 

#top-bar li a {

  padding: 1px 0.9em;

 }

}

 

#page-title,

#action-area h1 {

    margin: 0;

    text-align: center;

}

 

#page-title {

    margin-top: -0.35rem;

    font-weight: bold;

    font-size: 4.5em;

 

    color: rgb(var(--secondary-color));

    border-color: transparent;

 

    display: var(--title-setting) !important;

    flex-direction: column;

    align-items: center;

    position: relative;

}

 

#page-title::after {

   content: var(--subtitle-content);

 

   display: var(--subtitle-setting);

   width: 100%;

   height: 2rem;

 

   margin-top: -1.5rem;

   justify-content: center;

   align-items: center;

   font-size: 30%;

   letter-spacing: 1px;

}

 

#breadcrumbs, .pseudocrumbs {

    margin: 1em 0 -1em;

}

 

#content-wrap {

    position: relative;

 

    max-width: none;

    margin: 0;

 

    overflow: hidden;

    top: var(--display-mode);

 

    background: linear-gradient(to bottom, transparent, rgb(var(--primary-color), 0.75) 15vh, rgb(var(--primary-color), 0.75));

