@import url('https://fonts.googleapis.com/css2?family=Roboto+Slab:wght@700&display=swap');



div.dream table {

  width: 50%;

  border-style: hidden;

  text-align: center;

}

div.dream td {

width: 25%;

  text-align: center;

  border-style: hidden;

}



/* == VOID - OUTER CSS == */

 div.void {

    width: 40%;

    margin: 1rem;

    padding: 0 .8rem;

float: left;

    color: hsl(0, 0%, 5%);

    background: hsl(0, 0%, 100%);

    border: 1px solid lightgray;

    box-shadow: 3px 3px 0 1px hsla(0, 0%, 0%, .15);

}



 @media (max-width: 767px) {

     div.void {

     width: auto;

    }

}



/* == VOID - INNER CSS == */

 div.void span {

    word-break: unset;

}



 .vusermod {

    font-weight: bold;

}



 div.void ul {

    list-style-type: "☁ ";

}



/* == VOID - AVATAR == */

 .void-img {

    float: left;

    margin: 1rem 0 0 .4rem;

    padding: 0 1rem;

}



/* == VOID - TRENDS == */

 .vactivity {

    color: blue;

    cursor: pointer;

}



 .vactivity span {

    word-break: unset;

}



 .vactivity:hover,

 .vactivity:focus {

    text-decoration: underline;

}



/* == RATEMYDIRECTOR == */



div.rating {

float: right;

width: 45%;

margin: 2rem;

background: #fff;

padding: .3rem 1.5rem;

border-radius: 2rem;

box-shadow: 3px 3px 5px 2px rgba(0,0,0,0.15);

border-top: 4px solid red;

}



.rating hr {

    border-top: 2px solid red;

}



.ratee:before {

  content: "VENDOR: ";

  font-family: 'Roboto Slab', serif;

  font-size: 1rem;

  color: red;

}



.ratee {

    font-family: 'Roboto Slab', serif;

    font-size: 125%;

}



.stars {

    font-size: 130%;

    float: right;

}



